-- Korpus basis pengetahuan. DIHASILKAN oleh scripts/bangun_korpus.py.
--
-- Setiap potongan adalah kutipan apa adanya dari halaman sumbernya,
-- bukan ringkasan dan bukan tulisan ulang. Setiap dokumen punya URL
-- yang sudah diverifikasi menjawab HTTP 200 saat berkas ini dibuat.
--
-- Kolom `embedding` sengaja dibiarkan kosong: mengisinya perlu kunci
-- API Gemini. Tanpa itu `cari_potongan()` tetap bekerja lewat jalur
-- teks penuh Bahasa Indonesia. Jalankan scripts/index_corpus.py bila
-- kunci sudah tersedia.

delete from dokumen_pengetahuan where id::text like 'c0000000-%';

